// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

/// @title OracleRound
/// @notice Commit-then-reveal reporting by independent data providers.
/// Each provider first commits sha256(...) of its result with a secret salt, so no
/// provider can see another's answer before committing. Commitments use sha256 (not
/// keccak) so a standard-library Python verifier can recompute them.
abstract contract OracleRound {
    struct Report {
        bytes32 commitment;
        bool revealed;
        bool outcome; // true = the agreed trigger condition was met
        uint16 longestSpell; // longest qualifying run of days the provider computed
        bytes32 evidenceDigest; // sha256 of the provider's canonical evidence bundle
    }

    mapping(uint256 => mapping(address => Report)) internal reports;
    mapping(uint256 => uint256) public commitCount;
    mapping(uint256 => uint256) public revealCount;

    event Committed(uint256 indexed agreementId, address indexed provider, bytes32 commitment);
    event Revealed(
        uint256 indexed agreementId,
        address indexed provider,
        bool outcome,
        uint16 longestSpell,
        bytes32 evidenceDigest
    );

    error AlreadyCommitted();
    error NotCommitted();
    error AlreadyRevealed();
    error CommitmentMismatch();
    error EmptyCommitment();

    /// @notice The exact preimage layout the verifier recomputes:
    /// sha256(abi.encodePacked(contract, chainId, agreementId, provider, outcome, longestSpell, evidenceDigest, salt))
    function commitmentOf(
        uint256 agreementId,
        address provider,
        bool outcome,
        uint16 longestSpell,
        bytes32 evidenceDigest,
        bytes32 salt
    ) public view returns (bytes32) {
        return sha256(
            abi.encodePacked(address(this), block.chainid, agreementId, provider, outcome, longestSpell, evidenceDigest, salt)
        );
    }

    function getReport(uint256 agreementId, address provider) external view returns (Report memory) {
        return reports[agreementId][provider];
    }

    function _commit(uint256 agreementId, address provider, bytes32 commitment) internal {
        if (commitment == bytes32(0)) revert EmptyCommitment();
        Report storage r = reports[agreementId][provider];
        if (r.commitment != bytes32(0)) revert AlreadyCommitted();
        r.commitment = commitment;
        commitCount[agreementId] += 1;
        emit Committed(agreementId, provider, commitment);
    }

    function _reveal(
        uint256 agreementId,
        address provider,
        bool outcome,
        uint16 longestSpell,
        bytes32 evidenceDigest,
        bytes32 salt
    ) internal {
        Report storage r = reports[agreementId][provider];
        if (r.commitment == bytes32(0)) revert NotCommitted();
        if (r.revealed) revert AlreadyRevealed();
        if (commitmentOf(agreementId, provider, outcome, longestSpell, evidenceDigest, salt) != r.commitment) {
            revert CommitmentMismatch();
        }
        r.revealed = true;
        r.outcome = outcome;
        r.longestSpell = longestSpell;
        r.evidenceDigest = evidenceDigest;
        revealCount[agreementId] += 1;
        emit Revealed(agreementId, provider, outcome, longestSpell, evidenceDigest);
    }
}

