// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

interface ITriggerAgreement {
    function finalize(uint256 id) external;
    function settleDisputeByDefault(uint256 id) external;
    function cancel(uint256 id) external;
}

/// @notice Test-only hostile token: on every outgoing transfer it tries to re-enter the
/// escrow to settle the same agreement again. Records whether the re-entry succeeded.
contract ReentrantToken {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    address public target;
    uint256 public targetId;
    uint8 public mode; // 0 off, 1 finalize, 2 settleDisputeByDefault, 3 cancel
    bool public reentered;
    bool public reentrySucceeded;

    function mint(address to, uint256 v) external {
        balanceOf[to] += v;
    }

    function arm(address t, uint256 id, uint8 m) external {
        target = t;
        targetId = id;
        mode = m;
    }

    function approve(address s, uint256 v) external returns (bool) {
        allowance[msg.sender][s] = v;
        return true;
    }

    function transferFrom(address f, address to, uint256 v) external returns (bool) {
        allowance[f][msg.sender] -= v;
        balanceOf[f] -= v;
        balanceOf[to] += v;
        return true;
    }

    function transfer(address to, uint256 v) external returns (bool) {
        balanceOf[msg.sender] -= v;
        balanceOf[to] += v;
        if (mode != 0 && !reentered) {
            reentered = true;
            bytes memory data;
            if (mode == 1) data = abi.encodeCall(ITriggerAgreement.finalize, (targetId));
            else if (mode == 2) data = abi.encodeCall(ITriggerAgreement.settleDisputeByDefault, (targetId));
            else data = abi.encodeCall(ITriggerAgreement.cancel, (targetId));
            (bool ok,) = target.call(data);
            reentrySucceeded = ok;
        }
        return true;
    }
}

